import numpy as np, scipy.sparse as sp, scipy.sparse.linalg as spla, random, copy
from reference import Task

def fast_eigs(A, k, v0, maxiter, ncv, tol):
    return spla.eigs(A, k=k, v0=v0, maxiter=maxiter, ncv=ncv, tol=tol)

def residuals(A, eigvals, eigvecs):
    res=[]
    for lam, vec in zip(eigvals, eigvecs.T):
        r=A.dot(vec)-lam*vec
        res.append(np.linalg.norm(r))
    return np.array(res)

def fast_solve(problem):
    A=problem['matrix']; k=problem['k']; N=A.shape[0]
    v0=np.ones(N, dtype=A.dtype)
    param_sets=[
        dict(tol=1e-4, maxiter=int(N*20), ncv=15),
        dict(tol=1e-6, maxiter=int(N*100), ncv=20),
        dict(tol=0, maxiter=int(N*200), ncv=20)
    ]
    for ps in param_sets:
        try:
            vals, vecs= fast_eigs(A,k,v0, **ps)
        except Exception as e:
            continue
        res = residuals(A, vals, vecs)
        if np.all(res < 1e-5):
            break
    pairs=list(zip(vals, vecs.T))
    pairs.sort(key=lambda p:-abs(p[0]))
    return [p[1] for p in pairs]

task=Task();
fail_count=0
for seed in random.sample(range(1_000_000), 200):
    p=task.generate_problem(n=300, random_seed=seed)
    sol=fast_solve(copy.deepcopy(p))
    if not task.is_solution(p, sol):
        print('fail', seed)
        fail_count+=1
        break
else:
    print('all pass')
